/* Which icon each element gets (set on the parent, read by ::before) */
.drawer-icon.fa-sliders { --vg-ic: var(--vg-ic-sliders); }
.drawer-icon.fa-plug-circle-exclamation,
.drawer-icon.fa-plug { --vg-ic: var(--vg-ic-plug); }
.drawer-icon.fa-font { --vg-ic: var(--vg-ic-type); }
.drawer-icon.fa-book-atlas { --vg-ic: var(--vg-ic-book); }
.drawer-icon.fa-user-cog { --vg-ic: var(--vg-ic-settings); }
.drawer-icon.fa-panorama { --vg-ic: var(--vg-ic-image); }
.drawer-icon.fa-cubes { --vg-ic: var(--vg-ic-blocks); }
.drawer-icon.fa-face-smile { --vg-ic: var(--vg-ic-user); }
.drawer-icon.fa-address-card { --vg-ic: var(--vg-ic-users); }
#options_button.fa-bars { --vg-ic: var(--vg-ic-menu); }
#send_but.fa-paper-plane { --vg-ic: var(--vg-ic-send); }
.swipe_left.fa-chevron-left { --vg-ic: var(--vg-ic-chevron-l); }
.swipe_right.fa-chevron-right { --vg-ic: var(--vg-ic-chevron-r); }
.mes_button.extraMesButtonsHint.fa-ellipsis { --vg-ic: var(--vg-ic-ellipsis); }
.mes_button.mes_edit.fa-pencil { --vg-ic: var(--vg-ic-pencil); }
#extensionsMenuButton.fa-magic-wand-sparkles { --vg-ic: var(--vg-ic-wand); }
.right_menu_button.fa-lock { --vg-ic: var(--vg-ic-lock); }
.right_menu_button.fa-unlock { --vg-ic: var(--vg-ic-lock-open); }
#mes_impersonate.fa-user-secret { --vg-ic: var(--vg-ic-ghost); }
#mes_continue.fa-arrow-right { --vg-ic: var(--vg-ic-arrow-r); }
#mes_stop > .fa-circle-stop { --vg-ic: var(--vg-ic-stop); }
.mes_edit_done.fa-check { --vg-ic: var(--vg-ic-check); }
.mes_edit_copy.fa-copy { --vg-ic: var(--vg-ic-copy); }
.mes_edit_add_reasoning.fa-lightbulb { --vg-ic: var(--vg-ic-bulb); }
.mes_edit_delete.fa-trash-can { --vg-ic: var(--vg-ic-trash); }
.mes_edit_up.fa-chevron-up { --vg-ic: var(--vg-ic-chevron-u); }
.mes_edit_down.fa-chevron-down { --vg-ic: var(--vg-ic-chevron-d); }
.mes_edit_cancel.fa-xmark { --vg-ic: var(--vg-ic-x); }

/* Replacement mechanics — selector list must mirror the mapping above so an
   unmapped icon never gets a blank mask */
.drawer-icon.fa-sliders::before,
.drawer-icon.fa-plug-circle-exclamation::before,
.drawer-icon.fa-plug::before,
.drawer-icon.fa-font::before,
.drawer-icon.fa-book-atlas::before,
.drawer-icon.fa-user-cog::before,
.drawer-icon.fa-panorama::before,
.drawer-icon.fa-cubes::before,
.drawer-icon.fa-face-smile::before,
.drawer-icon.fa-address-card::before,
#options_button.fa-bars::before,
#send_but.fa-paper-plane::before,
.swipe_left.fa-chevron-left::before,
.swipe_right.fa-chevron-right::before,
.mes_button.extraMesButtonsHint.fa-ellipsis::before,
.mes_button.mes_edit.fa-pencil::before,
#extensionsMenuButton.fa-magic-wand-sparkles::before,
.right_menu_button.fa-lock::before,
.right_menu_button.fa-unlock::before,
#mes_impersonate.fa-user-secret::before,
#mes_continue.fa-arrow-right::before,
#mes_stop > .fa-circle-stop::before,
.mes_edit_done.fa-check::before,
.mes_edit_copy.fa-copy::before,
.mes_edit_add_reasoning.fa-lightbulb::before,
.mes_edit_delete.fa-trash-can::before,
.mes_edit_up.fa-chevron-up::before,
.mes_edit_down.fa-chevron-down::before,
.mes_edit_cancel.fa-xmark::before {
    content: '';
    display: inline-block;
    width: 1.1em;
    height: 1.1em;
    background-color: currentColor;
    mask: var(--vg-ic) center / contain no-repeat;
    vertical-align: -0.17em;
}

/* The send plane is diagonal, so at 1.1em its tips reach the circular
   button's clip edge — size it down within the filled circle */
#send_but.fa-paper-plane::before {
    width: 0.8em;
    height: 0.8em;
}

/* Chip treatment: every top-bar icon sits in a consistent rounded hit-area;
   the open drawer carries an accent-filled chip. The glyph is scaled down so
   the chip's outer box stays within --topBarBlockSize (ST sizes the bar off
   the raw glyph; an untouched font-size would overflow the bar). */
.drawer-icon {
    display: inline-grid;
    place-items: center;
    font-size: calc(var(--topBarIconSize) * 0.62);
    width: 1.75em;
    height: 1.75em;
    padding: 0;
    border-radius: var(--vg-radius-m);
    border: 1px solid transparent;
}

.drawer-icon:hover {
    background-color: var(--vg-accent-soft);
    border-color: var(--vg-glass-border);
}

.drawer-icon.openIcon {
    background-color: var(--vg-accent-soft);
    border-color: var(--vg-accent-border);
    color: var(--vg-accent-strong);
}

/* --------------------------------------------------------------------------
   13c. Calm chrome
   Secondary controls rest dimmed and sharpen on approach. Pure opacity —
   nothing moves, nothing is hidden, hit-areas are unchanged.
   -------------------------------------------------------------------------- */
.mes .mes_buttons {
    opacity: 0.45;
}

.mes:hover .mes_buttons,
.mes .mes_buttons:focus-within {
    opacity: 1;
}

.drawer-content .range-block,
.drawer-content .checkbox_label {
    opacity: 0.78;
}

.drawer-content .range-block:hover,
.drawer-content .range-block:focus-within,
.drawer-content .checkbox_label:hover,
.drawer-content .checkbox_label:focus-within {
    opacity: 1;
}

/* Micro-label typography: setting names become small uppercase letterspaced
   labels — the strongest single "designed system" signal in dense panels */
.drawer-content .range-block-title,
.drawer-content h4,
.drawer-content h5 {
    font-size: 0.74em;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    opacity: 0.8;
}

/* --------------------------------------------------------------------------
   14. Motion
   Everything here is transform/opacity only and double-gated: rules sit
   behind body:not(.reduced-motion) (ST adds the class for both its setting
   and the OS preference), and a prefers-reduced-motion media query below is
   the belt-and-braces kill switch.
   -------------------------------------------------------------------------- */
@keyframes vg-rise-in {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

@keyframes vg-drawer-in {
    from {
        opacity: 0;
        transform: translateY(-6px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

/* Toast entrance is transform-only: toastr runs its own jQuery opacity fade
   and a keyframe touching opacity would fight it. */
@keyframes vg-toast-in {
    from {
        transform: translateY(-8px);
    }

    to {
        transform: none;
    }
}

body:not(.reduced-motion) #chat .mes {
    animation: vg-rise-in 280ms var(--vg-ease-out);
}

/* Keyframes only — ST drives drawer open/close geometry (height transitions
   with allow-discrete); a transition on height/display here would fight it. */
body:not(.reduced-motion) .drawer-content.openDrawer {
    animation: vg-drawer-in 220ms var(--vg-ease-out);
}

body:not(.reduced-motion) #toast-container>div {
    animation: vg-toast-in 240ms var(--vg-ease-out);
}

body:not(.reduced-motion) #send_but,
body:not(.reduced-motion) .drawer-icon {
    transition: transform var(--vg-dur-fast) var(--vg-ease-spring);
}

body:not(.reduced-motion) #send_but:hover {
    transform: scale(1.08);
}

body:not(.reduced-motion) #send_but:active {
    transform: scale(0.94);
}

body:not(.reduced-motion) .drawer-icon:hover {
    transform: scale(1.1);
}

body:not(.reduced-motion) .menu_button {
    transition:
        background-color var(--vg-dur-fast) var(--vg-ease-out),
        border-color var(--vg-dur-fast) var(--vg-ease-out),
        transform var(--vg-dur-fast) var(--vg-ease-out);
}

body:not(.reduced-motion) .menu_button:hover {
    transform: translateY(-1px);
}

body:not(.reduced-motion) #send_form::after {
    transition: opacity 200ms var(--vg-ease-out);
}

body:not(.reduced-motion) .drawer-icon {
    transition:
        transform var(--vg-dur-fast) var(--vg-ease-spring),
        background-color var(--vg-dur-fast) var(--vg-ease-out),
        border-color var(--vg-dur-fast) var(--vg-ease-out);
}

body:not(.reduced-motion) .mes .mes_buttons,
body:not(.reduced-motion) .drawer-content .range-block,
body:not(.reduced-motion) .drawer-content .checkbox_label {
    transition: opacity var(--vg-dur-fast) var(--vg-ease-out);
}

body:not(.reduced-motion) #leftSendForm > div,
body:not(.reduced-motion) #rightSendForm > div:not(.mes_stop) {
    transition:
        opacity var(--vg-dur-fast) var(--vg-ease-out),
        background-color var(--vg-dur-fast) var(--vg-ease-out);
}

@media (prefers-reduced-motion: reduce) {

    #chat .mes,
    .drawer-content.openDrawer,
    #toast-container>div {
        animation: none !important;
    }

    #send_but,
    .drawer-icon,
    .menu_button,
    #send_form::after,
    .mes .mes_buttons,
    .drawer-content .range-block,
    .drawer-content .checkbox_label,
    #leftSendForm > div,
    #rightSendForm > div:not(.mes_stop) {
        transition: none !important;
    }
}
